CREATE TEMP TABLE tgt ON COMMIT DROP AS SELECT x.*, p.id AS publisher_id FROM prof x
  JOIN countries c ON c.iso_code = x.iso JOIN publishers p ON p.country_id = c.id AND p.name = x.name
  JOIN publisher_submissions s ON s.publisher_id = p.id AND s.verification_detail LIKE '%' || $t$[added by Claude 2026-10-19, Build #97 thin-coverage countries]$t$;
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM tgt;
  IF n <> 8 THEN RAISE EXCEPTION 'found % of 8 Build #97 publishers by name and country - nothing changed', n; END IF;
  SELECT count(*) INTO n FROM tgt t JOIN editorial_profiles e ON e.publisher_id = t.publisher_id;
  IF n > 0 THEN RAISE EXCEPTION '% already have a profile - nothing changed', n; END IF;
  INSERT INTO editorial_profiles (publisher_id, ownership_type, owner, classification_tags, political_party_association, historical_context,
    current_context, confidence, evidence_summary, evidence_sources, classification_date, last_reviewed, evidence_date, review_required)
  SELECT publisher_id, ownership_type, owner, classification_tags, NULL, historical_context, current_context, confidence, evidence_summary,
    evidence_sources, DATE '2026-10-19', DATE '2026-10-19', DATE '2026-10-19', review_required FROM tgt;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 8 THEN RAISE EXCEPTION 'inserted %, expected 8', n; END IF;
END $$;
SELECT 'profile|' || p.id || '|' || p.name || '|' || array_to_string(e.classification_tags, ',') || '|' || e.confidence || '|review ' || e.review_required
       || '|' || jsonb_array_length(e.evidence_sources) || ' sources'
  FROM editorial_profiles e JOIN publishers p ON p.id = e.publisher_id WHERE e.publisher_id IN (SELECT publisher_id FROM tgt) ORDER BY p.id;
SELECT 'gap|' || count(*) || ' active publishers without a profile'
  FROM publishers p LEFT JOIN editorial_profiles e ON e.publisher_id = p.id WHERE p.feed_status = 'active' AND e.id IS NULL;
